import requests

def test_get_admin_wallet_topup_requests_returns_pending_queue():
    base_url = "http://localhost:8000"
    token = "eyJhbGciOiJFUzI1NiIsImtpZCI6ImI4MTI2OWYxLTIxZDgtNGYyZS1iNzE5LWMyMjQwYTg0MGQ5MCIsInR5cCI6IkpXVCJ9..7tnorXc_v1GajgbKOx_eL1YOszeBUfjHR8eD_sTpsMVGd1byScCiaea2NrexKmTDL3dIlmobE5Mqry_s39Blkw"
    headers = {
        "Authorization": f"Bearer {token}",
        "Accept": "application/json"
    }

    url = f"{base_url}/api/admin/wallet-topup-requests"

    try:
        response = requests.get(url, headers=headers, timeout=30)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        assert False, f"Request failed: {e}"

    assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"

    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    # Validate that the response is a list (queue) and each item has expected keys
    assert isinstance(data, list), "Response data should be a list"

    for item in data:
        assert isinstance(item, dict), "Each top-up request should be a dictionary"
        # Since it's pending queue, expect at least these keys (based on typical top-up request fields)
        expected_keys = {"id", "driver_id", "amount", "status", "created_at"}
        missing_keys = expected_keys - item.keys()
        assert not missing_keys, f"Top-up request item missing keys: {missing_keys}"
        assert item["status"].lower() == "pending", f"Top-up request status should be 'pending', got '{item['status']}'"

test_get_admin_wallet_topup_requests_returns_pending_queue()